IndexCommonItem = class("IndexCommonItem")

function IndexCommonItem:ctor()
end

function IndexCommonItem:InitPanel(gameObject)
    self.gameObject = gameObject;
    self.transform = gameObject.transform;
    self:FindComponent(self.transform);
    self.callback = nil;
    self.index = 0;
    EventDelegate.Add(self.trigger.onClick,EventDelegate.Callback(function() self:ItemClick() end));
end

function IndexCommonItem:ItemClick()
    if self.callback ~= nil then
        self.callback(self.index);
    end
end

function IndexCommonItem:FindComponent(transform)
    local tTransform = transform;
    self.trigger = Util.FindChildEx(tTransform,""):GetComponent("UIEventTrigger");
    self.unchoose = Util.FindChildEx(tTransform,"unchoose").gameObject;
    self.choose = Util.FindChildEx(tTransform,"choose").gameObject;
    self.lab_sortName1 = Util.FindChildEx(tTransform,"unchoose/lab_sortName"):GetComponent("UILabel");
    self.lab_sortName2 = Util.FindChildEx(tTransform,"choose/lab_sortName"):GetComponent("UILabel");
end

function IndexCommonItem:Init(data, callback)
    self.index = data.index;
    self.lab_sortName1.text = data.title;
    self.lab_sortName2.text = data.title;
    self.callback = callback;
end

function IndexCommonItem:ChangeState(show)
    self.choose:SetActive(show);
    self.unchoose:SetActive(not show);
end